 21	const <PID> = function _sip_handleStore(sip_notebookId)
 22	{
 23	  const IDB_NAME = 'lopecode-save-in-place';
 24	  const STORE = 'handles';
 25	  const key = sip_notebookId || 'default';
 26	  const openDB = () => new Promise((resolve, reject) => {
 27	    const req = window.indexedDB.open(IDB_NAME, 1);
 28	    req.onupgradeneeded = () => req.result.createObjectStore(STORE);
 29	    req.onsuccess = () => resolve(req.result);
 30	    req.onerror = () => reject(req.error);
 31	  });
 32	  const get = async () => {
 33	    const db = await openDB();
 34	    return new Promise((resolve, reject) => {
 35	      const r = db.transaction(STORE, 'readonly').objectStore(STORE).get(key);
 36	      r.onsuccess = () => resolve(r.result);
 37	      r.onerror = () => reject(r.error);
 38	    });
 39	  };
 40	  const put = async handle => {
 41	    const db = await openDB();
 42	    return new Promise((resolve, reject) => {
 43	      const tx = db.transaction(STORE, 'readwrite');
 44	      tx.objectStore(STORE).put(handle, key);
 45	      tx.oncomplete = () => resolve();
 46	      tx.onerror = () => reject(tx.error);
 47	    });
 48	  };
 49	  const del = async () => {
 50	    const db = await openDB();
 51	    return new Promise((resolve, reject) => {
 52	      const tx = db.transaction(STORE, 'readwrite');
 53	      tx.objectStore(STORE).delete(key);
 54	      tx.oncomplete = () => resolve();
 55	      tx.onerror = () => reject(tx.error);
 56	    });
 57	  };
 58	  return {
 59	    get,
 60	    put,
 61	    del,
 62	    key
 63	  };
 64	};
