100	        busy: 'var(--theme-foreground-focus, #6cb0ff)',
101	        muted: 'var(--theme-foreground-muted, #888)'
102	      };
103	      el.style.background = 'var(--theme-background-raised, var(--theme-background-b, #fff))';
104	      el.style.color = 'var(--theme-foreground, #000)';
105	      el.style.borderLeftColor = accent[k] || accent.busy;
106	      el.style.opacity = '1';
107	    };
108	    const hide = ms => {
109	      el.__sipTimer = window.setTimeout(() => {
110	        el.style.opacity = '0';
111	        el.style.transition = 'opacity .<T>';
112	      }, ms);
113	    };
114	    paint(msg, kind);
115	    if (kind && kind !== 'busy')
116	      hide(kind === 'err' ? 5000 : 2200);
117	    return {
118	      done: (text, k) => {
119	        paint(text, k);
120	        hide(k === 'err' ? 5000 : 2200);
121	      }
122	    };
123	  };
124	};
