128	const <PID> = function _sip_save(sip_handleStore,location,sip_toast,exportToHTML,runtime)
129	{
130	  const store = sip_handleStore;
131	  // current layout, minus volatile params, becomes the saved file's boot hash
132	  const cleanHash = () => {
133	    const raw = String(location.hash || '').replace(/^#/, '');
134	    const drop = new Set([
135	      'cc',
136	      'open',
137	      'close',
138	      'filesync',
139	      'from',
140	      'focus'
141	    ]);
142	    const kept = raw.split('&').filter(Boolean).filter(p => !drop.has(p.split('=')[0]));
143	    return kept.length ? '#' + kept.join('&') : '';
144	  };
145	  const acquire = async () => {
146	    const saved = await store.get().catch(() => null);
147	    if (saved) {
148	      let perm = 'granted';
149	      if (saved.queryPermission)
150	        perm = await saved.queryPermission({ mode: 'readwrite' }).catch(() => 'denied');
151	      if (perm !== 'granted' && saved.requestPermission)
152	        perm = await saved.requestPermission({ mode: 'readwrite' }).catch(() => 'denied');
153	      if (perm === 'granted')
154	        return saved;
155	    }
156	    if (!window.showSaveFilePicker)
157	      throw new Error('File System Access API unavailable (needs Chromium + a secure context)');
158	    const suggested = (document.title || 'notebook').replace(/[^\w.-]+/g, '_').replace(/^_+|_+$/g, '') || 'notebook';
159	    const handle = await window.showSaveFilePicker({
160	      suggestedName: suggested + '.html',
161	      types: [{
162	          description: 'HTML',
163	          accept: { 'text/html': ['.html'] }
164	        }]
165	    });
166	    await store.put(handle).catch(() => {
167	    });
168	    return handle;
169	  };
170	  const save = async () => {
171	    const toast = sip_toast('Saving\u2026', 'busy');
172	    try {
173	      const handle = await acquire();
174	      // pass mains explicitly (like exporter-3's exportAnchor) — a bare call leaves
175	      // bootconf mains empty and the saved file boots blank. runtime.mains re-includes
176	      // every booted main, so the saved copy keeps save-in-place too.
177	      const resp = await exportToHTML({
178	        mains: new Map(runtime.mains),
179	        runtime,
180	        options: { hash: cleanHash() }
181	      });
182	      const html = resp?.source ?? resp;
183	      if (typeof html !== 'string' || html.length < 1000)
184	        throw new Error('export produced no source');
185	      const writable = await handle.createWritable();
186	      await writable.write(html);
187	      await writable.close();
188	      toast.done('Saved \u2713 ' + handle.name, 'ok');
189	      return {
190	        ok: true,
191	        name: handle.name,
192	        bytes: html.length
193	      };
194	    } catch (e) {
195	      if (e && e.name === 'AbortError') {
196	        toast.done('Save cancelled', 'muted');
197	        return {
198	          ok: false,
199	          cancelled: true
200	        };
201	      }
202	      toast.done('Save failed: ' + (e && e.message || e), 'err');
203	      throw e;
204	    }
205	  };
206	  return save;
207	};
